        "Usage: java -jar vineflower.jar --<option>=<value>... <source>... <destination>\n" +
        "Example: java -jar vineflower.jar --decompile-generics ./MyJar.jar ./out_files\n\n" +
        "Use -h or --help for more information.");
      return;
    }

